def tcksift2_execute(params: Tcksift2, runner: Runner | None = None) -> Tcksift2Outputs:
    """
    tcksift2

    Optimise per-streamline cross-section multipliers to match a whole-brain tractogram to fixel-wise fibre densities.



References:

Smith, R. E.; Tournier, J.-D.; Calamante, F. & Connelly, A. SIFT2: Enabling dense quantitative assessment of brain white matter connectivity using streamlines tractography. NeuroImage, 2015, 119, 338-351

* If using the -linear option: 
Smith, RE; Raffelt, D; Tournier, J-D; Connelly, A. Quantitative Streamlines Tractography: Methods and Inter-Subject Normalisation. Open Science Framework, https://doi.org/10.31219/osf.io/c67kn.

    Author: MRTrix3 Developers

    URL: https://www.mrtrix.org/

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    tcksift2_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(TCKSIFT2_METADATA)
    execution.params(params)
    args = tcksift2_cargs(params, execution)
    out = tcksift2_outputs(params, execution)
    execution.run(args)
    return out

def tcksift2(
    in_tracks: InputPathType,
    in_fod: InputPathType,
    out_weights: str,
    proc_mask: InputPathType | None = None,
    act: InputPathType | None = None,
    fd_scale_gm: bool = False,
    no_dilate_lut: bool = False,
    make_null_lobes: bool = False,
    remove_untracked: bool = False,
    fd_thresh: float | None = None,
    csv: str | None = None,
    out_mu: str | None = None,
    output_debug: bool = False,
    out_coeffs: str | None = None,
    reg_tikhonov: float | None = None,
    reg_tv: float | None = None,
    min_td_frac: float | None = None,
    min_iters: int | None = None,
    max_iters: int | None = None,
    min_factor: float | None = None,
    min_coeff: float | None = None,
    max_factor: float | None = None,
    max_coeff: float | None = None,
    max_coeff_step: float | None = None,
    min_cf_decrease: float | None = None,
    linear: bool = False,
    info: bool = False,
    quiet: bool = False,
    debug: bool = False,
    force: bool = False,
    nthreads: int | None = None,
    config: list[Tcksift2Config] | None = None,
    help: bool = False,
    version: bool = False,
    runner: Runner | None = None,
) -> Tcksift2Outputs:
    """
    tcksift2

    Optimise per-streamline cross-section multipliers to match a whole-brain tractogram to fixel-wise fibre densities.



References:

Smith, R. E.; Tournier, J.-D.; Calamante, F. & Connelly, A. SIFT2: Enabling dense quantitative assessment of brain white matter connectivity using streamlines tractography. NeuroImage, 2015, 119, 338-351

* If using the -linear option: 
Smith, RE; Raffelt, D; Tournier, J-D; Connelly, A. Quantitative Streamlines Tractography: Methods and Inter-Subject Normalisation. Open Science Framework, https://doi.org/10.31219/osf.io/c67kn.

    Author: MRTrix3 Developers

    URL: https://www.mrtrix.org/

    Args:
        in_tracks: the input track file
        in_fod: input image containing the spherical harmonics of the fibre\
            orientation distributions
        out_weights: output text file containing the weighting factor for each\
            streamline
        proc_mask: provide an image containing the processing mask weights for the\
            model; image spatial dimensions must match the fixel image
        act: use an ACT five-tissue-type segmented anatomical image to derive the\
            processing mask
        fd_scale_gm: provide this option (in conjunction with -act) to\
            heuristically downsize the fibre density estimates based on the\
            presence of GM in the voxel. This can assist in reducing tissue\
            interface effects when using a single-tissue deconvolution algorithm
        no_dilate_lut: do NOT dilate FOD lobe lookup tables; only map streamlines\
            to FOD lobes if the precise tangent lies within the angular spread of\
            that lobe
        make_null_lobes: add an additional FOD lobe to each voxel, with zero\
            integral, that covers all directions with zero / negative FOD\
            amplitudes
        remove_untracked: remove FOD lobes that do not have any streamline density\
            attributed to them; this improves filtering slightly, at the expense of\
            longer computation time (and you can no longer do quantitative\
            comparisons between reconstructions if this is enabled)
        fd_thresh: fibre density threshold; exclude an FOD lobe from filtering\
            processing if its integral is less than this amount (streamlines will\
            still be mapped to it, but it will not contribute to the cost function\
            or the filtering)
        csv: output statistics of execution per iteration to a .csv file
        out_mu: output the final value of SIFT proportionality coefficient mu to a\
            text file
        output_debug: provide various output images for assessing & debugging\
            performance etc.
        out_coeffs: output text file containing the weighting coefficient for each\
            streamline
        reg_tikhonov: provide coefficient for regularising streamline weighting\
            coefficients (Tikhonov regularisation) (default: 0)
        reg_tv: provide coefficient for regularising variance of streamline\
            weighting coefficient to fixels along its length (Total Variation\
            regularisation) (default: 0.1)
        min_td_frac: minimum fraction of the FOD integral reconstructed by\
            streamlines; if the reconstructed streamline density is below this\
            fraction, the fixel is excluded from optimisation (default: 0.1)
        min_iters: minimum number of iterations to run before testing for\
            convergence; this can prevent premature termination at early iterations\
            if the cost function increases slightly (default: 10)
        max_iters: maximum number of iterations to run before terminating program
        min_factor: minimum weighting factor for an individual streamline; if the\
            factor falls below this number the streamline will be rejected entirely\
            (factor set to zero) (default: 0)
        min_coeff: minimum weighting coefficient for an individual streamline;\
            similar to the '-min_factor' option, but using the exponential\
            coefficient basis of the SIFT2 model; these parameters are related as:\
            factor = e^(coeff). Note that the -min_factor and -min_coeff options\
            are mutually exclusive - you can only provide one. (default: -inf)
        max_factor: maximum weighting factor that can be assigned to any one\
            streamline (default: inf)
        max_coeff: maximum weighting coefficient for an individual streamline;\
            similar to the '-max_factor' option, but using the exponential\
            coefficient basis of the SIFT2 model; these parameters are related as:\
            factor = e^(coeff). Note that the -max_factor and -max_coeff options\
            are mutually exclusive - you can only provide one. (default: inf)
        max_coeff_step: maximum change to a streamline's weighting coefficient in a\
            single iteration (default: 1)
        min_cf_decrease: minimum decrease in the cost function (as a fraction of\
            the initial value) that must occur each iteration for the algorithm to\
            continue (default: 2.5e-05)
        linear: perform a linear estimation of streamline weights, rather than the\
            standard non-linear optimisation (typically does not provide as\
            accurate a model fit; but only requires a single pass)
        info: display information messages.
        quiet: do not display information messages or progress status;\
            alternatively, this can be achieved by setting the MRTRIX_QUIET\
            environment variable to a non-empty string.
        debug: display debugging messages.
        force: force overwrite of output files (caution: using the same file as\
            input and output might cause unexpected behaviour).
        nthreads: use this number of threads in multi-threaded applications (set to\
            0 to disable multi-threading).
        config: temporarily set the value of an MRtrix config file entry.
        help: display this information page and exit.
        version: display version information and exit.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = tcksift2_params(
        in_tracks=in_tracks,
        in_fod=in_fod,
        out_weights=out_weights,
        proc_mask=proc_mask,
        act=act,
        fd_scale_gm=fd_scale_gm,
        no_dilate_lut=no_dilate_lut,
        make_null_lobes=make_null_lobes,
        remove_untracked=remove_untracked,
        fd_thresh=fd_thresh,
        csv=csv,
        out_mu=out_mu,
        output_debug=output_debug,
        out_coeffs=out_coeffs,
        reg_tikhonov=reg_tikhonov,
        reg_tv=reg_tv,
        min_td_frac=min_td_frac,
        min_iters=min_iters,
        max_iters=max_iters,
        min_factor=min_factor,
        min_coeff=min_coeff,
        max_factor=max_factor,
        max_coeff=max_coeff,
        max_coeff_step=max_coeff_step,
        min_cf_decrease=min_cf_decrease,
        linear=linear,
        info=info,
        quiet=quiet,
        debug=debug,
        force=force,
        nthreads=nthreads,
        config=config,
        help=help,
        version=version,
    )
    return tcksift2_execute(params, runner)

